// The business sites from ONE list, k8s/sites/sites.json (ADRs 0047, 0049). Plain Node, repo root:
//
//   node k8s/scripts/sites.mjs --write   (npm run sites:generate) writes every site's files
//   node k8s/scripts/sites.mjs --check   (npm run k8s:check, CI) refuses a generated file that
//                                        differs, and an environment that misses a site's settings
//
// Generated, per site <id> (never edit them by hand: change this script or sites.json):
//   k8s/sites/<id>/app/kustomization.yaml       the template (k8s/sites/_template) with its names
//   k8s/sites/<id>/kustomization.yaml           the Component an environment lists: host and URLs
//   k8s/sites/<id>/keycloak/kustomization.yaml  its Keycloak files + its realm's public path
//   k8s/sites/<id>/keycloak/site-<id>.json      its client in nest-microservice: service account
//   k8s/sites/<id>/keycloak/customers-<id>.json realm site-<id>: its customers; the security
//                                               settings are realm.json's, read here (no drift)
//   k8s/components/keycloak-local/test-customers-<id>.json  bob and carol (dev, staging)
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';

const root = join(import.meta.dirname, '..', '..');
const k8s = (...parts) => join(root, 'k8s', ...parts);
const read = (path) => readFileSync(path, 'utf8');
const json = (value) => `${JSON.stringify(value, null, 2)}\n`;
const { sites } = JSON.parse(read(k8s('sites/sites.json')));

/** Settings every realm shares with nest-microservice (base/keycloak/realm.json). */
const SHARED_REALM_SETTINGS = [
  'sslRequired',
  'loginWithEmailAllowed',
  'bruteForceProtected',
  'permanentLockout',
  'maxTemporaryLockouts',
  'bruteForceStrategy',
  'failureFactor',
  'waitIncrementSeconds',
  'maxFailureWaitSeconds',
  'maxDeltaTimeSeconds',
  'quickLoginCheckMilliSeconds',
  'minimumQuickLoginWaitSeconds',
  'accessTokenLifespan',
  'ssoSessionMaxLifespan',
  'revokeRefreshToken',
  'refreshTokenMaxReuse',
];
const TEST_PASSWORD = 'Dev-Staging-2026!'; // dev and staging only (components/keycloak-local)

function files(site) {
  const { id, name } = site;
  const ID = id.toUpperCase();
  const app = `${id}-web`;
  const staff = JSON.parse(read(k8s('base/keycloak/realm.json')));
  const shared = Object.fromEntries(SHARED_REALM_SETTINGS.map((key) => [key, staff[key]]));
  return {
    [`sites/${id}/app/kustomization.yaml`]: `# ${name} (web/apps/${app}): the business-site template with this site's names.
# Generated by \`npm run sites:generate\` from k8s/sites/sites.json: don't edit by hand.
apiVersion: kustomize.config.k8s.io/v1beta1
kind: Kustomization

configMapGenerator:
  - name: site
    options:
      annotations:
        config.kubernetes.io/local-config: 'true' # read by the template, never deployed
    literals:
      - APP=${app}
      - CLIENT_SECRET_KEY=${ID}_WEB_CLIENT_SECRET
      - REALM=site-${id}
      - 'REDIS_KEY_PREFIX=${app}:'

components:
  - ../../_template

# Read by the template; then dropped here, so that several sites can sit in one environment.
patches:
  - patch: |-
      $patch: delete
      apiVersion: v1
      kind: ConfigMap
      metadata:
        name: site
`,
    [`sites/${id}/kustomization.yaml`]: `# ${name} in an environment: list this component in the overlay. It brings the site (app/:
# Deployment, Service, route), its Keycloak files (keycloak/) and writes its addresses from the
# overlay's urls.env: ${ID}_HOST (the route), ${ID}_URL (APP_URL), AUTH_URL (its customers' realm).
# The overlay also needs what \`npm run k8s:check\` lists for it (image, client secret, Secret ${app}).
# Generated by \`npm run sites:generate\` from k8s/sites/sites.json: don't edit by hand.
apiVersion: kustomize.config.k8s.io/v1alpha1
kind: Component

resources:
  - app

components:
  - keycloak

replacements:
  - source: { kind: ConfigMap, name: public-urls, fieldPath: data.${ID}_HOST }
    targets:
      - select: { kind: HTTPRoute, name: ${app} }
        fieldPaths:
          - spec.hostnames.0
  - source: { kind: ConfigMap, name: public-urls, fieldPath: data.AUTH_URL }
    targets:
      - select: { kind: Deployment, name: ${app} }
        fieldPaths:
          - spec.template.spec.containers.[name=web].env.[name=KEYCLOAK_ISSUER].value
        options: { delimiter: '/realms/', index: 0 }
  - source: { kind: ConfigMap, name: public-urls, fieldPath: data.${ID}_URL }
    targets:
      - select: { kind: Deployment, name: ${app} }
        fieldPaths:
          - spec.template.spec.containers.[name=web].env.[name=APP_URL].value
`,
    [`sites/${id}/keycloak/kustomization.yaml`]: `# ${name}: its Keycloak client ${app} in nest-microservice (service account, group /sites/${id},
# content:read; ADR 0032) and realm site-${id} for its customers (ADR 0049), applied by the Job
# keycloak-config. Its secret: ${ID}_WEB_CLIENT_SECRET of the overlay's Secret "keycloak-clients".
# Dev lists only this part (the sites run on the developer's machine).
# Generated by \`npm run sites:generate\` from k8s/sites/sites.json: don't edit by hand.
apiVersion: kustomize.config.k8s.io/v1alpha1
kind: Component

configMapGenerator:
  - name: keycloak-config
    behavior: merge
    files:
      - site-${id}.json
      - customers-${id}.json

# Its customers' sign-in pages are public: /realms/site-${id} on the auth.* route (base/gateway).
patches:
  - target: { kind: HTTPRoute, name: auth }
    patch: |-
      - op: add
        path: /spec/rules/0/matches/-
        value: { path: { type: PathPrefix, value: /realms/site-${id} } }
`,
    [`sites/${id}/keycloak/site-${id}.json`]: json({
      realm: 'nest-microservice',
      clients: [
        {
          clientId: app,
          name: `${app} server (public site): service account that READS the site's published content (ADR 0032)`,
          enabled: true,
          publicClient: false,
          clientAuthenticatorType: 'client-secret',
          secret: `$(env:${ID}_WEB_CLIENT_SECRET)`,
          standardFlowEnabled: false,
          implicitFlowEnabled: false,
          directAccessGrantsEnabled: false,
          serviceAccountsEnabled: true,
          fullScopeAllowed: true,
          protocolMappers: [
            {
              name: 'audience-content-api',
              protocol: 'openid-connect',
              protocolMapper: 'oidc-audience-mapper',
              consentRequired: false,
              config: { 'included.client.audience': 'content-api', 'id.token.claim': 'false', 'access.token.claim': 'true', 'introspection.token.claim': 'true' },
            },
            {
              name: 'groups',
              protocol: 'openid-connect',
              protocolMapper: 'oidc-group-membership-mapper',
              consentRequired: false,
              config: {
                'claim.name': 'groups',
                'full.path': 'true',
                'id.token.claim': 'false',
                'access.token.claim': 'true',
                'userinfo.token.claim': 'false',
                'introspection.token.claim': 'true',
              },
            },
          ],
        },
      ],
      users: [
        {
          username: `service-account-${app}`,
          enabled: true,
          serviceAccountClientId: app,
          clientRoles: { 'content-api': ['content:read'] },
          groups: [`/sites/${id}`],
        },
      ],
    }),
    [`sites/${id}/keycloak/customers-${id}.json`]: json({
      realm: `site-${id}`,
      displayName: name,
      enabled: true,
      ...shared,
      // Customers stay signed in longer than staff (8 h idle in nest-microservice).
      ssoSessionIdleTimeout: 86400,
      // No e-mail is sent (no SMTP): no self-registration, no "forgot password" yet.
      registrationAllowed: false,
      resetPasswordAllowed: false,
      rememberMe: false,
      internationalizationEnabled: true,
      supportedLocales: site.locales,
      defaultLocale: site.defaultLocale,
      clients: [
        {
          clientId: app,
          name: `${app}: its customers sign in (BFF, confidential; ADR 0049)`,
          enabled: true,
          publicClient: false,
          clientAuthenticatorType: 'client-secret',
          secret: `$(env:${ID}_WEB_CLIENT_SECRET)`,
          standardFlowEnabled: true,
          implicitFlowEnabled: false,
          directAccessGrantsEnabled: false,
          serviceAccountsEnabled: false,
          redirectUris: [`$(env:${ID}_URL)/auth/callback`],
          webOrigins: [],
          attributes: { 'pkce.code.challenge.method': 'S256', 'post.logout.redirect.uris': `$(env:${ID}_URL)/*` },
          fullScopeAllowed: false,
        },
      ],
    }),
    [`components/keycloak-local/test-customers-${id}.json`]: json({
      realm: `site-${id}`,
      users: ['bob', 'carol'].map((username) => ({
        username,
        email: `${username}@example.com`,
        firstName: username[0].toUpperCase() + username.slice(1),
        lastName: 'Customer',
        enabled: true,
        emailVerified: true,
        credentials: [{ type: 'password', value: TEST_PASSWORD, temporary: false }],
      })),
    }),
  };
}

/** KEY=value of an env file (comments and blank lines skipped). */
function envFile(path) {
  if (!existsSync(path)) return {};
  return Object.fromEntries(
    read(path)
      .split('\n')
      .map((line) => line.trim())
      .filter((line) => line && !line.startsWith('#') && line.includes('='))
      .map((line) => [line.slice(0, line.indexOf('=')), line.slice(line.indexOf('=') + 1)]),
  );
}

/** What each environment must have for each site (written by hand there, checked here). */
function environmentProblems() {
  const problems = [];
  const has = (file, text) => read(k8s(file)).includes(text);
  for (const { id, devPort } of sites) {
    const ID = id.toUpperCase();
    const app = `${id}-web`;
    const devUrl = `http://localhost:${devPort}`;
    if (!has('overlays/dev/kustomization.yaml', `- ../../sites/${id}/keycloak`)) problems.push(`overlays/dev: components: - ../../sites/${id}/keycloak`);
    if (envFile(k8s('overlays/dev/urls.env'))[`${ID}_URL`] !== devUrl) problems.push(`overlays/dev/urls.env: ${ID}_URL=${devUrl}`);
    for (const env of ['staging', 'prod']) {
      if (!has(`overlays/${env}/kustomization.yaml`, `- ../../sites/${id}\n`)) problems.push(`overlays/${env}: components: - ../../sites/${id}`);
      const urls = envFile(k8s(`overlays/${env}/urls.env`));
      for (const key of [`${ID}_HOST`, `${ID}_URL`]) if (!urls[key]) problems.push(`overlays/${env}/urls.env: ${key}`);
    }
    if (!has('overlays/staging/secrets.yaml', `${ID}_WEB_CLIENT_SECRET:`) || !has('overlays/staging/secrets.yaml', `name: ${app}\n`)) problems.push(`overlays/staging/secrets.yaml: ${ID}_WEB_CLIENT_SECRET in keycloak-clients and Secret ${app}`);
    if (!has('overlays/prod/secrets/external-secrets.yaml', `secretKey: ${ID}_WEB_CLIENT_SECRET`) || !has('overlays/prod/secrets/external-secrets.yaml', `name: ${app}\n`)) problems.push(`overlays/prod/secrets/external-secrets.yaml: ${ID}_WEB_CLIENT_SECRET in keycloak-clients and ExternalSecret ${app}`);
    if (!has('components/local-data/redis/users.acl', `user ${app} on `)) problems.push(`components/local-data/redis/users.acl: user ${app} (keys ~${app}:*)`);
    if (!has('components/keycloak-local/kustomization.yaml', `- test-customers-${id}.json`)) problems.push(`components/keycloak-local/kustomization.yaml: - test-customers-${id}.json`);
    if (!JSON.parse(read(k8s('images.json'))).images.some((image) => image.name === app)) problems.push(`images.json: an entry for ${app} (siteUrl "{${ID}_URL}")`);
    const example = join(root, 'web/apps', app, '.env.example');
    if (!existsSync(example)) problems.push(`web/apps/${app}: the app (on @web/site-kit)`);
    else if (envFile(example).APP_URL !== devUrl) problems.push(`web/apps/${app}/.env.example: APP_URL=${devUrl}`);
  }
  const listed = new Set(sites.map((site) => site.id));
  for (const dir of readdirSync(k8s('sites'), { withFileTypes: true })) {
    if (dir.isDirectory() && dir.name !== '_template' && !listed.has(dir.name)) problems.push(`k8s/sites/${dir.name}: not in sites.json (add it, or remove the folder)`);
  }
  return problems;
}

const mode = process.argv[2];
if (mode !== '--write' && mode !== '--check') {
  console.error('usage: node k8s/scripts/sites.mjs --write | --check');
  process.exit(2);
}
const generated = Object.assign({}, ...sites.map(files));
const stale = [];
for (const [path, content] of Object.entries(generated)) {
  const file = k8s(path);
  if (existsSync(file) && read(file) === content) continue;
  if (mode === '--write') {
    mkdirSync(dirname(file), { recursive: true });
    writeFileSync(file, content);
    console.log(`wrote ${relative(root, file)}`);
  } else {
    stale.push(relative(root, file));
  }
}
const problems = environmentProblems();
if (mode === '--write') {
  if (problems.length) console.log(`\nStill to do by hand (k8s/README.md, "Business sites"):\n${problems.map((p) => `  - ${p}`).join('\n')}`);
  else console.log(`sites: ${sites.length} sites generated, every environment has their settings`);
  process.exit(0);
}
if (stale.length || problems.length) {
  console.error(
    `sites: ${stale.length + problems.length} problem(s)\n` +
      stale.map((path) => `  - ${path}: differs from what npm run sites:generate writes (never edit it by hand)\n`).join('') +
      problems.map((p) => `  - missing: ${p}\n`).join(''),
  );
  process.exit(1);
}
console.log(`sites: ${sites.length} sites from k8s/sites/sites.json, generated files and environments consistent`);
